let fallback,config,record,id,language=localStorage.getItem('white-swan-lang')||'ru',calendarCursor,observer;
const t=k=>dict[language]?.[k]||dict.ru[k]||k,locale=()=>config.locales?.[language]||config.locales.ru,dateObj=()=>new Date(config.date),localeCode=()=>language==='ky'?'ky-KG':language==='kk'?'kk-KZ':'ru-RU';
async function load(){fallback=await fetch('content.json').then(r=>r.json());id=invitationIdFromPath(location.pathname,fallback.backend.defaultId);try{const r=await fetch(`${fallback.backend.baseUrl}/${id}`,{headers:{Accept:'application/json'},cache:'no-store'});if(!r.ok)throw 0;record=await r.json();config=adaptXanoInvitation(record,fallback);$('#dataError').hidden=true}catch{config=fallback;record=null;$('#dataError').hidden=false}const enabled=config.enabledLanguages||['ru','ky'];if(!enabled.includes(language))language=config.defaultLanguage||enabled[0];$$('[data-lang]').forEach(b=>b.hidden=!enabled.includes(b.dataset.lang));$('#languageToggle').hidden=enabled.length<2;calendarCursor=dateObj();render();requestAnimationFrame(updateFeather);startHeroVideo()}
function dateText(opts){return new Intl.DateTimeFormat(localeCode(),{timeZone:config.timezone||'Asia/Bishkek',...opts}).format(dateObj()).replace(' г.','')}
function render(){document.documentElement.lang=language;$$('[data-lang]').forEach(x=>x.classList.toggle('active',x.dataset.lang===language));$('.language-menu__current').textContent=language==='ky'?'KG':language==='kk'?'KZ':'RU';$$('[data-i18n]').forEach(x=>x.innerHTML=t(x.dataset.i18n));const n=config.names;for(const key of ['heroFirst','footerFirst'])$('#'+key).textContent=n.first;for(const key of ['heroSecond','footerSecond'])$('#'+key).textContent=n.second;$('#heroAnd').textContent=language==='ru'?'и':language==='ky'?'жана':'және';$('.hero h1').classList.toggle('long-names',(n.first+n.second).length>16);$('#heroDay').textContent=dateText({day:'2-digit'});$('#heroMonth').textContent=dateText({month:'long'}).toUpperCase();$('#heroYear').textContent=dateText({year:'numeric'});$('#dateTitle').innerHTML=`${dateText({day:'numeric',month:'long'})} <em>${dateText({year:'numeric'})}</em>`;$('#footerDate').textContent=dateText({day:'numeric',month:'long',year:'numeric'});
 const l=locale();$('#welcomeTitle').textContent=l.welcomeTitle||t('dear');$('#welcomeText').textContent=l.welcome||'';$('#hostsText').textContent=l.hosts||'';$('#eventList').replaceChildren(...(l.schedule||[]).map(x=>{const li=document.createElement('li');li.className='event-item reveal';li.innerHTML=`<time class="event-time">${safe(x.time)}</time><div class="event-copy"><h3>${safe(x.title)}</h3><p>${safe(x.description)}</p></div>`;return li}));$('#venueType').textContent=l.venue.type;$('#venueName').textContent=l.venue.name;$('#venueAddress').textContent=l.venue.address;$('#venueTime').textContent=l.schedule?.[0]?.time||'';
 const mapBox=$('.map-buttons');mapBox.hidden=!config.map?.enabled;$('#googleMapLink').hidden=!config.map?.googleUrl;$('#twoGisLink').hidden=!config.map?.twoGisUrl;$('#googleMapLink').href=config.map?.googleUrl||'#';$('#twoGisLink').href=config.map?.twoGisUrl||'#';
 const wish=$('#wishBlock');wish.hidden=!config.wishBlock?.enabled;if(!wish.hidden){$('#wishBlockTitle').textContent=l.wishTitle;$('#wishBlockText').textContent=l.wishText}
 $('#rsvp').hidden=config.rsvp?.enabled===false;$('#guestWishField').hidden=config.rsvp?.allowGuestWish===false;configureGuestCount();
 document.title=`${n.first} & ${n.second} — ${dateText({day:'numeric',month:'long',year:'numeric'})}`;$('meta[name="description"]').content=`${l.welcomeTitle||t('invite')} — ${n.first} & ${n.second}`;renderCalendar();observe()}
function safe(v){const d=document.createElement('div');d.textContent=String(v||'');return d.innerHTML}
function renderCalendar(){const y=calendarCursor.getFullYear(),m=calendarCursor.getMonth(),wedding=dateObj();$('#calendarMonth').textContent=new Intl.DateTimeFormat(localeCode(),{month:'long',year:'numeric'}).format(calendarCursor);$('#calendarWeek').replaceChildren(...t('week').map(x=>Object.assign(document.createElement('span'),{textContent:x})));const first=(new Date(y,m,1).getDay()+6)%7,count=new Date(y,m+1,0).getDate(),cells=[];for(let i=0;i<first;i++){const s=document.createElement('span');s.className='empty';cells.push(s)}for(let d=1;d<=count;d++){const s=document.createElement('span');s.textContent=d;if(y===wedding.getFullYear()&&m===wedding.getMonth()&&d===wedding.getDate())s.className='wedding';cells.push(s)}$('#calendarDays').replaceChildren(...cells)}
function configureGuestCount(){const select=$('#guestCount'),max=config.rsvp?.maxGuests||10;select.replaceChildren(...Array.from({length:max},(_,i)=>Object.assign(document.createElement('option'),{value:String(i+1),textContent:String(i+1)})))}
function observe(){observer?.disconnect();observer=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.13});$$('.reveal:not(.visible)').forEach(x=>observer.observe(x))}
let ticking=false;function updateFeather(){ticking=false;const section=$('#events'),feather=$('#featherFlight');if(!section||matchMedia('(prefers-reduced-motion:reduce)').matches)return;const r=section.getBoundingClientRect(),range=section.offsetHeight+innerHeight*.5,p=Math.max(0,Math.min(1,(innerHeight*.65-r.top)/range)),s=Math.sin(p*Math.PI*4);feather.style.left=`${50+s*22}%`;feather.style.transform=`translate3d(-50%,${p*Math.max(0,section.offsetHeight-430)}px,0) rotate(${s*24-12}deg)`}addEventListener('scroll',()=>{if(!ticking){ticking=true;requestAnimationFrame(updateFeather)}},{passive:true});addEventListener('resize',updateFeather);
const languageMenu=$('.language-menu'),languageMenuToggle=$('.language-menu__toggle');
languageMenuToggle.addEventListener('click',()=>{const open=languageMenu.classList.toggle('is-open');languageMenuToggle.setAttribute('aria-expanded',String(open))});
document.addEventListener('click',event=>{if(!languageMenu.contains(event.target)){languageMenu.classList.remove('is-open');languageMenuToggle.setAttribute('aria-expanded','false')}});
$$('[data-lang]').forEach(button=>button.addEventListener('click',()=>{language=button.dataset.lang;localStorage.setItem('white-swan-lang',language);render();languageMenu.classList.remove('is-open');languageMenuToggle.setAttribute('aria-expanded','false')}));
$('#calendarDownload').addEventListener('click',()=>{const d=s=>new Date(s).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const text=`BEGIN:VCALENDAR\nVERSION:2.0\nBEGIN:VEVENT\nDTSTART:${d(config.date)}\nDTEND:${d(config.endDate)}\nSUMMARY:${config.names.first} & ${config.names.second}\nLOCATION:${locale().venue.address}\nEND:VEVENT\nEND:VCALENDAR`,a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/calendar'}));a.download='wedding.ics';a.click();URL.revokeObjectURL(a.href)});
$$('input[name="attending"]').forEach(x=>x.addEventListener('change',()=>$('#guestCountWrap').hidden=$('input[name="attending"]:checked').value==='no'));
$('#rsvpForm').addEventListener('submit',async e=>{e.preventDefault();const btn=$('#submitRsvp'),status=$('#formStatus'),attending=$('input[name="attending"]:checked').value==='yes',guest={name:$('#guestName').value,wish:$('#guestWish').value,guests_count:attending?Number($('#guestCount').value):0,is_attending:attending};btn.disabled=true;status.textContent=t('loading');try{if(!record)throw 0;const latestResponse=await fetch(`${fallback.backend.baseUrl}/${id}`,{cache:'no-store'});if(!latestResponse.ok)throw 0;const latest=await latestResponse.json(),body=createGuestPatch(latest,id,guest),r=await fetch(`${fallback.backend.baseUrl}/${id}/full`,{method:'PATCH',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify(body)});if(!r.ok)throw 0;record=body;config=adaptXanoInvitation(record,fallback);status.textContent=t('sent');e.target.reset();$('#guestCountWrap').hidden=false}catch{status.textContent=t('failed')}finally{btn.disabled=false}});
const heroVideo=$('#heroVideo');async function startHeroVideo(){heroVideo.muted=true;heroVideo.loop=true;try{await heroVideo.play()}catch{}}heroVideo.addEventListener('canplay',startHeroVideo);document.addEventListener('visibilitychange',()=>!document.hidden&&startHeroVideo());$('#dataRetry').addEventListener('click',load);load();
